+const cartCount = document.querySelector("[data-cart-count]");
+const toast = document.querySelector("[data-toast]");
+const navToggle = document.querySelector(".nav-toggle");
+const navLinks = document.querySelector("[data-nav-links]");
+const filterButtons = document.querySelectorAll("[data-filter]");
+const productCards = document.querySelectorAll("[data-category]");
+const newsletterForm = document.querySelector("[data-newsletter-form]");
+const formMessage = document.querySelector("[data-form-message]");
+
+let cartTotal = 0;
+let toastTimer;
+
+function showToast(message) {
+  toast.textContent = message;
+  toast.classList.add("show");
+  clearTimeout(toastTimer);
+  toastTimer = setTimeout(() => {
+    toast.classList.remove("show");
+  }, 2400);
+}
+
+document.querySelectorAll(".add-to-cart").forEach((button) => {
+  button.addEventListener("click", () => {
+    cartTotal += 1;
+    cartCount.textContent = cartTotal;
+    showToast(`${button.dataset.product} added to cart`);
+  });
+});
+
+navToggle.addEventListener("click", () => {
+  const isOpen = navLinks.classList.toggle("open");
+  navToggle.setAttribute("aria-expanded", String(isOpen));
+  navToggle.setAttribute("aria-label", isOpen ? "Close navigation" : "Open navigation");
+});
+
+navLinks.querySelectorAll("a").forEach((link) => {
+  link.addEventListener("click", () => {
+    navLinks.classList.remove("open");
+    navToggle.setAttribute("aria-expanded", "false");
+    navToggle.setAttribute("aria-label", "Open navigation");
+  });
+});
+
+filterButtons.forEach((button) => {
+  button.addEventListener("click", () => {
+    const selected = button.dataset.filter;
+
+    filterButtons.forEach((filterButton) => {
+      filterButton.classList.toggle("active", filterButton === button);
+    });
+
+    productCards.forEach((card) => {
+      const shouldShow = selected === "all" || card.dataset.category === selected;
+      card.hidden = !shouldShow;
+    });
+  });
+});
+
+function updateCountdown() {
+  const now = new Date();
+  const endDate = new Date(now);
+  endDate.setDate(now.getDate() + 2);
+  endDate.setHours(23, 59, 59, 999);
+
+  const difference = Math.max(0, endDate - now);
+  const minutesTotal = Math.floor(difference / 60000);
+  const days = Math.floor(minutesTotal / 1440);
+  const hours = Math.floor((minutesTotal % 1440) / 60);
+  const minutes = minutesTotal % 60;
+
+  document.querySelector("[data-days]").textContent = String(days).padStart(2, "0");
+  document.querySelector("[data-hours]").textContent = String(hours).padStart(2, "0");
+  document.querySelector("[data-minutes]").textContent = String(minutes).padStart(2, "0");
+}
+
+newsletterForm.addEventListener("submit", (event) => {
+  event.preventDefault();
+  const formData = new FormData(newsletterForm);
+  const email = formData.get("email");
+
+  formMessage.textContent = `Thanks! A welcome offer is headed to ${email}.`;
+  newsletterForm.reset();
+});
+
+updateCountdown();
+setInterval(updateCountdown, 60000);
